const markArenasStaleFromDate = `-- name: MarkArenasStaleFromDate :exec
UPDATE arenas
SET stale_at = NOW(),
    recalc_from = CASE
        WHEN arenas.stale_at IS NOT NULL AND arenas.recalc_from IS NULL THEN NULL
        WHEN arenas.recalc_from IS NULL THEN $1::timestamptz
        ELSE least(arenas.recalc_from, $1::timestamptz)
    END
WHERE id = ANY($2::uuid[])
`

type MarkArenasStaleFromDateParams struct {
	FromDate time.Time `json:"from_date"`
	ArenaIds []id.ID   `json:"arena_ids"`
}

// Incremental mark: widen the pending replay window to include @from_date.
// A pending full recalc (recalc_from IS NULL while stale) wins over dates.
func (q *Queries) MarkArenasStaleFromDate(ctx context.Context, arg MarkArenasStaleFromDateParams) error {
	_, err := q.db.Exec(ctx, markArenasStaleFromDate, arg.FromDate, arg.ArenaIds)
	return err
}

const markArenasStaleFull = `-- name: MarkArenasStaleFull :exec

UPDATE arenas
SET stale_at = NOW(), recalc_from = NULL
WHERE id = ANY($1::uuid[])
`

// ---------------------------------------------------------------------------
// Dirty queue
// ---------------------------------------------------------------------------
func (q *Queries) MarkArenasStaleFull(ctx context.Context, arenaIds []id.ID) error {
	_, err := q.db.Exec(ctx, markArenasStaleFull, arenaIds)
	return err
}

const updateArena = `-- name: UpdateArena :one
UPDATE arenas
SET name = $2, match_filter_id = $3, settings = $4, settings_schema_version = $5,
    camp = $6, starts_at = $7, ends_at = $8
WHERE id = $1
RETURNING id, name, match_filter_id, settings, settings_schema_version, game_id, tournament_id, recalc_from, stale_at, camp, starts_at, ends_at, club_id
`

type UpdateArenaParams struct {
	ID                    id.ID              `json:"id"`
	Name                  string             `json:"name"`
	MatchFilterID         *id.ID             `json:"match_filter_id"`
	Settings              json.RawMessage    `json:"settings"`
	SettingsSchemaVersion int32              `json:"settings_schema_version"`
	Camp                  bool               `json:"camp"`
	StartsAt              pgtype.Timestamptz `json:"starts_at"`
	EndsAt                pgtype.Timestamptz `json:"ends_at"`
}

func (q *Queries) UpdateArena(ctx context.Context, arg UpdateArenaParams) (Arena, error) {
	row := q.db.QueryRow(ctx, updateArena,
		arg.ID,
		arg.Name,
		arg.MatchFilterID,
		arg.Settings,
		arg.SettingsSchemaVersion,
		arg.Camp,
		arg.StartsAt,
		arg.EndsAt,
	)
	var i Arena
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.MatchFilterID,
		&i.Settings,
		&i.SettingsSchemaVersion,
		&i.GameID,
		&i.TournamentID,
		&i.RecalcFrom,
		&i.StaleAt,
		&i.Camp,
		&i.StartsAt,
		&i.EndsAt,
		&i.ClubID,
	)
	return i, err
}

const updateArenaName = `-- name: UpdateArenaName :exec
UPDATE arenas SET name = $2 WHERE id = $1
`

type UpdateArenaNameParams struct {
	ID   id.ID  `json:"id"`
	Name string `json:"name"`
}

// Name sync for auto-managed arenas when their game is renamed.
func (q *Queries) UpdateArenaName(ctx context.Context, arg UpdateArenaNameParams) error {
	_, err := q.db.Exec(ctx, updateArenaName, arg.ID, arg.Name)
	return err
}
